--!strict
-- Tunables for the living neighbourhood (Controllers/AmbientLife + helpers, client only). Positions live in
-- Config/AmbientMap (generated by tools/SurveyHoodLife.lua + tools/build_ambient_map.py, never typed by hand).
-- Pure maths in Rules/AmbientRules (tested by tools/tests/test_ambient_rules.py).
-- Sound ids: 0 = skip that sound (the system runs silently). Only public/free Creator Marketplace audio.
local C = Color3.fromRGB

local Ambient = {}

Ambient.Enabled = true

-- the one Heartbeat: near things every frame, far things at this rate
Ambient.FarHz = 10
Ambient.NearRadius = 70 -- inside this, people/cars/birds animate every frame

---------------------------------------------------------------- people
Ambient.People = {
	Max = 14, -- pool size (never more rigs than this)
	SpawnRadius = 160, -- people live within this of the camera
