---------------------------------------------------------------- sound (AmbientSound owns it all)
-- SoundService.MTL_Ambience (SoundGroup) holds every ambient sound: beds, emitters, cars, birds, people murmur.
-- Settings/mixers can turn the whole world down through that one group.
Ambient.Sound = {
	MaxAudible = 8, -- positional loops playing at once (beds don't count)
	Radius = 120, -- emitters further than this are never considered
	Crossfade = 2, -- seconds between zone / day-night beds
	-- zone beds: one day + one night loop each. Zones come from AmbientMap.Zones (alley, underpass, canal) and
	-- Config/Locations (shop interiors); everywhere else is "Street".
	Zones = {
		Street = { day = "StreetDay", night = "StreetNight" },
		Alley = { day = "AlleyDay", night = "AlleyNight" },
		Shop = { day = "ShopRoom", night = "ShopRoom" },
		Underpass = { day = "Underpass", night = "Underpass" },
