	-- to a model named `model...` within ShopFind studs of the Locations Inside/Door. `r` = fallback circle round Inside (any roof).
	-- Map 2026-11-02: FoodMart.InteriorV2 and BurgerShackV2 have their own floors under loose shell roofs that
	-- overhang the sidewalk; Westside Auto's floor is terrain, its roof is AutoShop's.
	Shops = {
		{ key = "FoodMart", model = "FoodMart", by = "floor", r = 10 }, -- glass front is 11.7 from Inside
		-- r = 0: their Locations.Inside sits on the sidewalk in front (under the shell's overhang), so no fallback circle
		{ key = "BurgerShack", model = "BurgerShack", by = "floor", r = 0 },
