	ShopFind = 110, -- the Food Mart is 110 studs wide; its far corner is ~86 from Inside
	-- ids: Creator Store, free. PSE = ProSoundEffects (Roblox-licensed SFX); music = Roblox's licensed Distrokid catalog.
